package com.food.controller;
import jakarta.servlet.http.HttpSession; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.ModelAndView; import com.food.dao.OrderDAO;
@Controller @RequestMapping("/orders") public class PlaceOrderController { @Autowired private OrderDAO orderDAO; @PostMapping("/place") public ModelAndView place(@RequestParam int restaurantId,@RequestParam String itemName,@RequestParam int quantity,@RequestParam String customerName,HttpSession session){if(session.getAttribute("username")==null)return new ModelAndView("redirect:/login"); orderDAO.placeOrder(restaurantId,itemName,quantity,customerName); ModelAndView mv=new ModelAndView("order-confirmation"); mv.addObject("itemName",itemName); mv.addObject("quantity",quantity); mv.addObject("customerName",customerName); return mv;} }
